#include <atomic>
#include <memory>
#include <iostream>

int main() {
    std::shared_ptr<int> ptr = std::make_shared<int>(42);
    std::atomic<std::shared_ptr<int>> atomic_ptr;
    // Store 'ptr' into 'atomic_ptr' with memory_order_release for synchronization
    std::atomic_store_explicit(&atomic_ptr, ptr, std::memory_order_release);
    // Load the value back with memory_order_acquire
    std::shared_ptr<int> loaded_ptr = std::atomic_load_explicit(&atomic_ptr, std::memory_order_acquire);
    std::cout << "Value: " << *loaded_ptr << std::endl;
    return 0;
}
